{"code": "import urllib.request, urllib.parse, json

base = "https://api.nal.usda.gov/fdc/v1/foods/search"
qs = urllib.parse.urlencode({
    "query": "Cheese, feta",
    "dataType": "SR Legacy",
    "pageSize": "10",
    "api_key": "DEMO_KEY"
})
req = urllib.request.Request(base + "?" + qs, headers={"User-Agent": "Mozilla/5.0"})
try:
    with urllib.request.urlopen(req, timeout=60) as resp:
        data = json.load(resp)
    for f in data.get("foods", [])[:10]:
        print(f.get("fdcId"), "|", f.get("description"), "|", f.get("dataType"), "| NDB:", f.get("ndbNumber"))
        for n in f.get("foodElements", []) or []:
            if n.get("nutrientName") == "Protein":
                print("    Protein:", n.get("value"), n.get("nutrientUnit"))
except Exception as e:
    print("ERROR:", type(e).__name__, e)
"}

